class TTLCache{constructor(max=5000){this.max=max;this.map=new Map()}set(k,v,ttl){this.map.set(k,{v,expires:Date.now()+ttl});this.cleanup();return v}get(k){const x=this.map.get(k);if(!x)return undefined;if(x.expires<=Date.now()){this.map.delete(k);return undefined}return x.v}delete(k){return this.map.delete(k)}cleanup(){const now=Date.now();for(const [k,x] of this.map)if(x.expires<=now)this.map.delete(k);while(this.map.size>this.max)this.map.delete(this.map.keys().next().value)}}module.exports=TTLCache;
